	d.VerificationResend.Max, d.VerificationResend.Window = 5, time.Hour
	d.Refresh.Max, d.Refresh.Window = 60, time.Minute
	d.APIKeyFailures.Max, d.APIKeyFailures.Window = 20, time.Minute
